//   iCE40HX4K-BG121 + W25Q128JVSIQ SPI boot flash, 25 MHz oscillator
//   HDMI Type-A: 3 data pairs + clock pair, DDC (level-shifted), HPD, +5V through PTC fuse
board "ice40_hdmi_node" {
  layers 6
  manufacturer "jlc-advanced"
  requires via_in_pad

  // Declared stack (assumption of this design, not a fabricator preset):
  // 1.6 mm. Pair layer L1 over the L2 ground plane through 0.11 mm prepreg.
  stackup {
    copper 0.035mm
    insulator 0.11mm er 4.2 material "prepreg"
    copper 0.0175mm
    insulator 0.36mm er 4.6 material "FR4 core"
    copper 0.0175mm
    insulator 0.52mm er 4.6 material "FR4 core"
    copper 0.0175mm
    insulator 0.36mm er 4.6 material "FR4 core"
    copper 0.0175mm
    insulator 0.11mm er 4.2 material "prepreg"
    copper 0.035mm
  }

  netclass "TMDS" {
    trace_width 0.13mm
    clearance 0.15mm
    via_diameter 0.46mm
    via_drill 0.2mm
    color "#d55e00"
  }
  netclass "PWR" {
    trace_width 0.4mm
    clearance 0.127mm
    via_diameter 0.46mm
    via_drill 0.2mm
    edge_rate slow
    color "#cc0000"
  }
  netclass "SIG" {
    trace_width 0.127mm
    clearance 0.127mm
    via_diameter 0.46mm
    via_drill 0.2mm
    edge_rate slow
    color "#0072b2"
  }
  netclass "CLK" {
    trace_width 0.127mm
    clearance 0.15mm
    via_diameter 0.46mm
