  // ---- LEDs and mounting --------------------------------------------------
  group "STATUS" color "#be185d" {
    component R20: resistor "r_generic_0603" value "470"
    component R21: resistor "r_generic_0603" value "470"
    component R22: resistor "r_generic_0603" value "470"
    component R23: resistor "r_generic_0603" value "470"
