    component D5: led "led_green_0603"
    component D6: led "led_red_0603"
    component D7: led "led_red_0603"
    component H1: mounting_hole "mounting_hole_m2_5"
    component H2: mounting_hole "mounting_hole_m2_5"
  }

  // ---- Nets ---------------------------------------------------------------
  net "+5V_IN" class "PWR" { J1.p1 F1.p1 }
  net "VIN_FUSED" class "PWR" { F1.p2 D1.cathode D2.anode }
  power "+5V" 5.0v class "PWR" { D2.cathode C1.p1 TP1.p1 U1.vin C2.p1 C3.p1 F2.p1 }
  power "+3V3" 3.3v class "PWR" {
    U1.vout C4.p1 C5.p1 TP2.p1 U2.vin U2.en C6.p1
    U3.vccio_0 U3.vccio_1 U3.vccio_2 U3.vccio_3 U3.vccio_3_2 U3.vcc_spi U3.vpp_2v5
    C14.p1 C15.p1 C16.p1 C17.p1 C18.p1 C19.p1 C20.p1
    U4.vcc C24.p1 R32.p1 R33.p1 R30.p1 R31.p1
    X1.vcc X1.oe C23.p1
    Q1.g Q2.g R11.p1 R12.p1 R20.p1
