    component U4: memory "w25q128jvsiq_208mil"
    component C24: capacitor "c_generic_0402" value "100nF" { placement_hint { near: "U4" priority: hard } }
    component R32: resistor "r_generic_0603" value "10k" { placement_hint { near: "U4" priority: hard } }
