    component R2: resistor "r_generic_0603" value "270" { placement_hint { near: "U3" priority: hard } }
    component R3: resistor "r_generic_0603" value "270" { placement_hint { near: "U3" priority: hard } }
    component R4: resistor "r_generic_0603" value "270" { placement_hint { near: "U3" priority: hard } }
    component R5: resistor "r_generic_0603" value "270" { placement_hint { near: "U3" priority: hard } }
    component R6: resistor "r_generic_0603" value "270" { placement_hint { near: "U3" priority: hard } }
    component R7: resistor "r_generic_0603" value "270" { placement_hint { near: "U3" priority: hard } }
    component R8: resistor "r_generic_0603" value "270" { placement_hint { near: "U3" priority: hard } }
    component F2: fuse "polyfuse_500ma" { placement_hint { near: "J2" priority: hard } }
