  }
  netclass "PWR" {
    trace_width 0.4mm
    clearance 0.127mm
    via_diameter 0.46mm
    via_drill 0.2mm
    edge_rate slow
    color "#cc0000"
  }
  netclass "SIG" {
    trace_width 0.127mm
    clearance 0.127mm
    via_diameter 0.46mm
    via_drill 0.2mm
    edge_rate slow
