  net "D2_P_SRC" class "TMDS_SRC" { U3.iol_23a R5.p1 }
  net "D2_N_SRC" class "TMDS_SRC" { U3.iol_23b R6.p1 }
  net "CK_P_SRC" class "TMDS_SRC" { U3.iol_12a R7.p1 }
  net "CK_N_SRC" class "TMDS_SRC" { U3.iol_12b R8.p1 }
  net "HDMI_D0_P" class "TMDS" { R1.p2 J2.d0_p }
