  net "D1_N_SRC" class "TMDS_SRC" { U3.iob_87 R4.p1 }
  net "D2_P_SRC" class "TMDS_SRC" { U3.iob_81_gbin5 R5.p1 }
  net "D2_N_SRC" class "TMDS_SRC" { U3.iob_94 R6.p1 }
  net "CK_P_SRC" class "TMDS_SRC" { U3.iot_208 R7.p1 }
