  stackup {
    copper 0.035mm
    insulator 0.11mm er 4.2 material "prepreg"
    copper 0.0175mm
    insulator 0.36mm er 4.6 material "FR4 core"
    copper 0.0175mm
    insulator 0.52mm er 4.6 material "FR4 core"
    copper 0.0175mm
    insulator 0.36mm er 4.6 material "FR4 core"
    copper 0.0175mm
    insulator 0.11mm er 4.2 material "prepreg"
    copper 0.035mm
  }

  netclass "TMDS" {
    trace_width 0.13mm
    clearance 0.127mm
    via_diameter 0.46mm
    via_drill 0.2mm
    layers "F.Cu"
    color "#d55e00"
  }
  netclass "TMDS_SRC" {
    trace_width 0.13mm
    clearance 0.127mm
    via_diameter 0.46mm
    via_drill 0.2mm
    color "#e69f00"
  }
  netclass "PWR" {
    trace_width 0.4mm
    clearance 0.127mm
    via_diameter 0.46mm
    via_drill 0.2mm
    edge_rate slow
    color "#cc0000"
  }
  netclass "SIG" {
    trace_width 0.127mm
    clearance 0.127mm
    via_diameter 0.46mm
    via_drill 0.2mm
    edge_rate slow
    color "#0072b2"
  }
  netclass "CLK" {
    trace_width 0.127mm
    clearance 0.15mm
    via_diameter 0.46mm
    via_drill 0.2mm
    color "#009e73"
  }

  // ---- Power entry --------------------------------------------------------
  group "POWER ENTRY" color "#c2410c" {
    component J1: connector "jst_b2b_xh_a_2pin" { placement_hint { edge: right priority: hard } }
    component F1: fuse "polyfuse_1r1a" { placement_hint { near: "J1" priority: hard } }
    component D1: diode "ptvs6v0s1ur" { placement_hint { near: "F1" priority: hard } }
